/**
 * Point-in-time lookup of the official CBR KZT/RUB rate effective on `requestedDate` (YYYY-MM-DD).
 * Never looks ahead to future dates (`record.date <= requestedDate`).
 * On weekends/holidays, returns the rate effective on that date (most recent CBR fixing <= requestedDate).
 */
export function lookupCbrKztRate(requestedDate) {
  const iso = String(requestedDate || "").slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) {
    return {
      status: "unavailable",
      reason: "invalid_date",
      requestedDate: requestedDate || null,
      effectiveDate: null,
      value: null,
      rawValue: null,
      nominal: 100,
    };
  }
  if (iso < CBR_KZT_DAILY_META.firstDate) {
    return {
      status: "unavailable",
      reason: "before_series_start",
      requestedDate: iso,
      effectiveDate: null,
      value: null,
      rawValue: null,
      nominal: 100,
    };
  }
  let lo = 0;
  let hi = CBR_KZT_DAILY_RECORDS.length - 1;
  let bestIdx = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (CBR_KZT_DAILY_RECORDS[mid].date <= iso) {
      bestIdx = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (bestIdx < 0) {
    return {
      status: "unavailable",
      reason: "not_found",
      requestedDate: iso,
      effectiveDate: null,
      value: null,
      rawValue: null,
      nominal: 100,
    };
  }
  const rec = CBR_KZT_DAILY_RECORDS[bestIdx];
  const prevRec = bestIdx > 0 ? CBR_KZT_DAILY_RECORDS[bestIdx - 1] : null;
  const changePct = prevRec && prevRec.value > 0
    ? +(((rec.value - prevRec.value) / prevRec.value) * 100).toFixed(4)
    : 0;
  return {
    status: rec.date === iso ? "official_cbr_exact" : "official_cbr_effective",
    requestedDate: iso,
    effectiveDate: rec.date,
    date: rec.date,
    asOf: rec.date,
    nominal: rec.nominal,
    rawValue: rec.rawValue,
    value: rec.value,
    changePct,
    valutaId: CBR_KZT_DAILY_META.valutaId,
    source: `ЦБ РФ R01335 на ${rec.date} (100 ₸ = ${rec.rawValue.toFixed(4)} ₽)`,
    sourceUrl: CBR_KZT_DAILY_META.sourceUrl,
    snapshotSha256: CBR_KZT_DAILY_META.snapshotSha256,
  };
}
